<?php include 'header.php';$dir=__DIR__.'/../uploads/gallery/';if(!is_dir($dir))mkdir($dir,0755,true);if(isset($_POST['upload'])&&isset($_FILES['image'])&&$_FILES['image']['error']===UPLOAD_ERR_OK){$ext=strtolower(pathinfo($_FILES['image']['name'],PATHINFO_EXTENSION));if(in_array($ext,['jpg','jpeg','png','webp'],true)){ $file=uniqid('gallery_',true).'.'.$ext; if(move_uploaded_file($_FILES['image']['tmp_name'],$dir.$file)){$pdo->prepare('INSERT INTO gallery(title,image) VALUES(?,?)')->execute([trim($_POST['title']??''),$file]);}}header('Location:gallery.php');exit;}if(isset($_GET['delete'])){$id=(int)$_GET['delete'];$s=$pdo->prepare('SELECT image FROM gallery WHERE id=?');$s->execute([$id]);$x=$s->fetch();if($x&&is_file($dir.$x['image']))unlink($dir.$x['image']);$pdo->prepare('DELETE FROM gallery WHERE id=?')->execute([$id]);header('Location:gallery.php');exit;}$rows=$pdo->query('SELECT * FROM gallery ORDER BY id DESC')->fetchAll(PDO::FETCH_ASSOC);?><h1>Gallery Management</h1><div class="panel"><form method="post" enctype="multipart/form-data"><input name="title" placeholder="ছবির শিরোনাম"><input type="file" name="image" accept="image/*" required><button name="upload">ছবি Upload</button></form></div><div class="gallery-admin"><?php foreach($rows as $r):?><div><img src="../uploads/gallery/<?=htmlspecialchars($r['image'])?>"><p><?=htmlspecialchars($r['title'])?></p><a class="danger" href="?delete=<?=$r['id']?>" onclick="return confirm('Delete?')">Delete</a></div><?php endforeach;?></div><?php include 'footer.php';?>